{
  "checks": {
    "P0051F0014": {
      "support": "supported",
      "claim_status": "observed",
      "source_origin": "research_note",
      "attribution_preserved": true,
      "note": "원문 p51:e364 캡션에 'total elapsed: 1342.47s'가 명시되어 있고, p51:e365에서 forward가 1342s까지 떨어졌다고 서술되어 실행인자 없는 forward 결과로 뒷받침된다. limits에 backward와 동일 수치라고 적혀 있으나 원문 캡션은 forward 실행 결과로 보인다."
    },
    "P0051F0015": {
      "support": "supported",
      "claim_status": "observed",
      "source_origin": "research_note",
      "attribution_preserved": true,
      "note": "원문 p51:e360 캡션에 'total elapsed: 1560.37s'가 있고 p51:e361에서 1560s가 나왔다고 언급되어 실행인자 없는 backward 결과로 뒷받침된다."
    },
    "P0052F0001": {
      "support": "supported",
      "claim_status": "observed",
      "source_origin": "research_note",
      "attribution_preserved": true,
      "note": "원문 p52:e373 캡션에 'total elapsed: 1447.17s'가 있고 p52:e374에서 실행인자 있는 forward라고 명시되어 있어 실행인자 있는 forward 결과로 뒷받침된다."
    },
    "P0052F0002": {
      "support": "supported",
      "claim_status": "interpretation",
      "source_origin": "research_note",
      "attribution_preserved": true,
      "note": "원문 p52:e380~p52:e381에 작성자가 정리한 3가지 의문이 그대로 기록되어 있어 작성자 해석/의문 진술로 뒷받침된다. 확정 원인은 제시되지 않았다."
    },
    "P0053F0001": {
      "support": "supported",
      "claim_status": "planned",
      "source_origin": "research_note",
      "attribution_preserved": true,
      "note": "원문 p53:e385에 발표 자료에서 비교를 한눈에 보이게 구성하고 표에서 강조할 부분을 따로 계산해서 넣는 등 표 강조 방식 개선 계획이 기록되어 있다."
    },
    "P0053F0002": {
      "support": "supported",
      "claim_status": "planned",
      "source_origin": "research_note",
      "attribution_preserved": true,
      "note": "원문 p53:e387에 Compute Throughput과 Memory Throughput의 정확한 정의(수식)를 알아보기로 한 계획이 기록되어 있다."
    },
    "P0053F0003": {
      "support": "supported",
      "claim_status": "hypothesis",
      "source_origin": "research_note",
      "attribution_preserved": true,
      "note": "원문 p53:e387에 memory throughput 비율 감소 원인으로 SM이 너무 바빠 메모리 병목이 생기는 경우를 떠올렸다는 가설이 기록되어 있다."
    },
    "P0053F0004": {
      "support": "supported",
      "claim_status": "planned",
      "source_origin": "research_note",
      "attribution_preserved": true,
      "note": "원문 p53:e387에 forward, backward 92만 번 실행에서 가끔 튀는 경우가 있어 평균과 분산을 구하기로 한 계획이 기록되어 있다."
    },
    "P0053F0005": {
      "support": "supported",
      "claim_status": "planned",
      "source_origin": "research_note",
      "attribution_preserved": true,
      "note": "원문 p53:e387에 추론 + bound + 검증을 모두 합쳐 측정하던 것을 각각 나눠 측정하기로 한 계획이 기록되어 있다."
    },
    "P0053F0006": {
      "support": "supported",
      "claim_status": "observed",
      "source_origin": "research_note",
      "attribution_preserved": true,
      "note": "원문 p53:e388에 92만 번의 forward, backward 측정을 20번씩 측정 완료했다고 기록되어 있다."
    },
    "P0053F0007": {
      "support": "supported",
      "claim_status": "observed",
      "source_origin": "research_note",
      "attribution_preserved": true,
      "note": "원문 p53:e388에 단일 데이터(optimizing.exe)에 대해 warm up이 얼마나 영향 미치는지 측정 및 검증 완료했다고 기록되어 있다."
    },
    "P0053F0008": {
      "support": "supported",
      "claim_status": "planned",
      "source_origin": "research_note",
      "attribution_preserved": true,
      "note": "원문 p53:e388에 sparse.py도 나눠서 측정하기로 하고 검증팀에 문의한 결과 따로 측정한 것은 없어 forward만 2번 더 측정하기로 했다고 기록되어 있다."
    },
    "P0053F0009": {
      "support": "supported",
      "claim_status": "planned",
      "source_origin": "research_note",
      "attribution_preserved": true,
      "note": "원문 p53:e388에 이후 sparse.py와 forward, backward 기준으로 각 평균 시간이 몇 배 차이나는지 검사하기로 했다고 기록되어 있다."
    },
    "P0053F0010": {
      "support": "supported",
      "claim_status": "planned",
      "source_origin": "research_note",
      "attribution_preserved": true,
      "note": "원문 p53:e389에 신경망 검증팀과 얘기해 forward, backward의 검증 비율 결과 차이가 이 정도 나는 것이 맞는지 검사하기로 했다고 기록되어 있다."
    },
    "P0053F0011": {
      "support": "supported",
      "claim_status": "planned",
      "source_origin": "research_note",
      "attribution_preserved": true,
      "note": "원문 p53:e389에 신경망 검증팀도 sweep으로 추론 + bound + 검증 92만 번 사이클을 한 번에 계산했는지 확인하기로 했다고 기록되어 있다."
    },
    "P0053F0012": {
      "support": "supported",
      "claim_status": "observed",
      "source_origin": "research_note",
      "attribution_preserved": true,
      "note": "원문 p53:e389에 확인 결과 forward와 backward의 차이, sweep 사이클 모두 맞다고 한다는 결과를 기록했다고 되어 있다."
    },
    "P0053F0013": {
      "support": "supported",
      "claim_status": "planned",
      "source_origin": "research_note",
      "attribution_preserved": true,
      "note": "원문 p53:e389에 TensorRT(Nvidia SDK)로 컴파일한 것과 직접 짠 nvcc 컴파일 시간을 비교하는 테스트를 고려했다고 기록되어 있다."
    },
    "P0053F0014": {
      "support": "supported",
      "claim_status": "planned",
      "source_origin": "research_note",
      "attribution_preserved": true,
      "note": "원문 p53:e385에 발표 자료에서 표를 넣을 때 한눈에 차이가 들어오게 구성하고 숫자 하나하나가 데이터에 들어오게 하거나 강조할 부분을 따로 계산해 넣는 방식으로 표 강조를 개선하기로 했다고 기록되어 있다."
    },
    "P0053F0015": {
      "support": "supported",
      "claim_status": "planned",
      "source_origin": "research_note",
      "attribution_preserved": true,
      "note": "원문 p53:e385에 대본을 보지 않고 발표자료에 말할 부분을 넣는 방식으로 발표 방식을 바꾸기로 했다고 기록되어 있다."
    },
    "P0054F0001": {
      "support": "supported",
      "claim_status": "documented_method",
      "source_origin": "research_note",
      "attribution_preserved": true,
      "note": "원문 p54:e392 코드 조각과 p54:e393 서술에 추론, bound 계산, 검증 끝마다 시간을 기록해 각각 측정하도록 코드를 구성했다고 되어 있어 문서화된 방법으로 뒷받침된다."
    },
    "P0054F0002": {
      "support": "supported",
      "claim_status": "observed",
      "source_origin": "research_note",
      "attribution_preserved": true,
      "note": "원문 p54:e394에 elapsed 타임(92만 번 계산 시간)과 미세한 오차가 있어 3개 누적 시간을 더한 값을 더 올바른 시간으로 보고 넣기로 했다고 기록되어 있다."
    },
    "P0054F0003": {
      "support": "supported",
      "claim_status": "observed",
      "source_origin": "research_note",
      "attribution_preserved": true,
      "note": "원문 p54:e395에 forward, backward 각각 20번 측정을 완료했고 튀는 값이 있어 각 20번 실행 시간의 평균과 분산을 구해 슬라이드에 넣을 예정이라고 기록되어 있다."
    },
    "P0054F0004": {
      "support": "supported",
      "claim_status": "documented_method",
      "source_origin": "research_note",
      "attribution_preserved": true,
      "note": "원문 p54:e397~p54:e398에 단일 데이터 측정 검증 과정에서 warm up 코드를 먼저 넣었다고 기록되어 있어 문서화된 방법으로 뒷받침된다."
    }
  }
}
